export async function api(url:string,data?:any){const res=await fetch('/api/'+url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result:any=await res.json();if(!res.ok){if(res.status===401&&!url.startsWith('auth/')&&typeof window!=='undefined')window.dispatchEvent(new Event('siap-session-expired'));throw new Error(result.error||'Permintaan gagal');}return result;}
