 const [reportYear,setReportYear]=useState(2027);
 const [page,setPage]=useState('beranda'),[section,setSection]=useState('dashboard'),[session,setSession]=useState<any>(null),[setup,setSetup]=useState(false),[demo,setDemo]=useState(false),[demoRole,setDemoRole]=useState('Administrator'),[data,setData]=useState<any>({usulan:[],companies:[],master:[],records:[],documents:[],notifications:[]}),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[profileOpen,setProfileOpen]=useState(false),[menu,setMenu]=useState(false),[sidebarOpen,setSidebarOpen]=useState(false),[dataMenu,setDataMenu]=useState(false),[year,setYear]=useState(''),[query,setQuery]=useState(''),[fs,setFs]=useState<string[]>([]),[mapKinds,setMapKinds]=useState<string[]>([]),[fw,setFw]=useState(''),[fb,setFb]=useState(''),[modal,setModal]=useState<any>(null),[selected,setSelected]=useState<any>(null),[users,setUsers]=useState<any[]>([]),[logs,setLogs]=useState<any[]>([]),[dataTab,setDataTab]=useState('Dasar Hukum'),[loginMode,setLoginMode]=useState('login');
 useEffect(()=>{if(session?.planning_year)setReportYear(Math.min(Number(session.planning_year),calendarYearWIB()));},[session?.planning_year]);
 const [publicSummary,setPublicSummary]=useState<any>(null);
 const [publicCompanies,setPublicCompanies]=useState<any[]>([]),[planningYears,setPlanningYears]=useState<number[]>([]),[printScope,setPrintScope]=useState(''),[printSnapshot,setPrintSnapshot]=useState<any>(null);
 const role=demo?demoRole:session?.role||'Publik';
