 async function load(){setLoading(true);setError('');try{const me=await api('me');setSession(me.user);setPlanningYears(me.years||[]);setSetup(me.setup);const selectedYear=me.user?.id===session?.id&&year?year:String(me.user?.planning_year||'');if(me.user?.planning_year)setYear(selectedYear);const loaded=await api(me.user?.planning_year?'workspace?planningYear='+selectedYear:'public');setData(loaded);const publicData=me.user?await api('public'):loaded;setPublicCompanies(publicData.companies);setPublicSummary(publicData.summary);}catch(e:any){setError(e.message);}finally{setLoading(false);}}
 useEffect(()=>{load();const p=new URL(location.href).searchParams.get('page');if(p)setPage(p);},[]);
