 useEffect(()=>{if(!session?.planning_year||demo||page!=='ruang-kerja')return;let alive=true,inFlight=false;const refresh=async()=>{if(inFlight)return;inFlight=true;try{const value=await api('workspace?planningYear='+(year||session.planning_year));if(alive)setData(value);}catch(e:any){if(alive)setToast(e.message);}finally{inFlight=false;}};const clicked=(event:MouseEvent)=>{const target=event.target as Element;if(target.closest('form,dialog,.assistantwidget,.user-profile-menu'))return;if(target.closest('.sidebar button,.workcontent button,.workspacebar button'))refresh();};refresh();document.addEventListener('click',clicked);return()=>{alive=false;document.removeEventListener('click',clicked);};},[session?.id,session?.planning_year,year,demo,page]);
